#!/usr/bin/env bash
# Brings the production host to the desired state. Idempotent: runs at first
# boot (EC2 user-data) and again on every deploy (SSM Run Command).
#
# Secrets are generated by CloudFormation in Secrets Manager and read here with
# the instance role; they are written only to a root-only .env file.
set -euo pipefail
exec > >(logger -t lendloop-bootstrap) 2>&1

: "${AWS_REGION:?}" "${BASE_DOMAIN:?}" "${SECRET_PREFIX:?}" "${BUNDLE_PARAM:?}" "${N8N_BUNDLE_PARAM:?}"
APP_DIR=/opt/lendloop
mkdir -p "$APP_DIR"
cd "$APP_DIR"

secret() { aws secretsmanager get-secret-value --region "$AWS_REGION" --secret-id "$SECRET_PREFIX/$1" --query SecretString --output text; }
param() { aws ssm get-parameter --region "$AWS_REGION" --name "$1" --query Parameter.Value --output text; }

# The public domain lives in SSM so a change reaches the host on the next run;
# BASE_DOMAIN from user-data (<ip>.sslip.io) is only the first-boot fallback.
BASE_DOMAIN=$(param /lendloop/prod/base-domain 2>/dev/null || echo "$BASE_DOMAIN")

# 1. Code bundle (compose file, Caddyfile, scripts) and the n8n workflows, both
#    CDK assets in the bootstrap bucket; the S3 URLs are published as SSM params.
aws s3 cp --region "$AWS_REGION" "$(param "$BUNDLE_PARAM")" /tmp/ec2.zip --only-show-errors
aws s3 cp --region "$AWS_REGION" "$(param "$N8N_BUNDLE_PARAM")" /tmp/n8n.zip --only-show-errors
# Empty the directory rather than replacing it: the running n8n container
# bind-mounts it, and a new directory would be invisible to it.
mkdir -p "$APP_DIR/n8n" && find "$APP_DIR/n8n" -mindepth 1 -delete
unzip -oq /tmp/ec2.zip -d "$APP_DIR"
unzip -oq /tmp/n8n.zip -d "$APP_DIR/n8n"
chmod +x "$APP_DIR"/*.sh

# 2. Environment for docker compose. The app URL is published by the web
#    stack once Amplify exists (links in emails); empty until then.
LENDLOOP_APP_URL=$(param /lendloop/prod/app-url 2>/dev/null || true)
#    Write the compose environment.
editor_password=$(secret N8N_EDITOR_PASSWORD)
editor_hash=$(docker run --rm caddy:2.10.2-alpine caddy hash-password --plaintext "$editor_password")
umask 077
cat > .env <<ENV
AWS_REGION=$AWS_REGION
BASE_DOMAIN=$BASE_DOMAIN
CONVEX_INSTANCE_SECRET=$(secret CONVEX_INSTANCE_SECRET | tr -d '\n' | sha256sum | cut -c1-64)
N8N_ENCRYPTION_KEY=$(secret N8N_ENCRYPTION_KEY)
LENDLOOP_TO_N8N_SECRET=$(secret LENDLOOP_TO_N8N_SECRET)
N8N_TO_LENDLOOP_SECRET=$(secret N8N_TO_LENDLOOP_SECRET)
N8N_EDITOR_HASH='$editor_hash'
LENDLOOP_APP_URL=${LENDLOOP_APP_URL:-}
ENV
chmod 600 .env
umask 022

# 3. Start or update the stack.
docker compose -f docker-compose.prod.yml pull --quiet
docker compose -f docker-compose.prod.yml up -d --remove-orphans
until curl -sf http://127.0.0.1:3210/version >/dev/null; do sleep 3; done

# 4. Convex admin key: generated once on the host and stored for CI (the
#    deploy workflow reads it as the scoped deploy user). Never printed.
if [ "$(secret CONVEX_ADMIN_KEY)" = "pending" ]; then
  key=$(docker compose -f docker-compose.prod.yml exec -T convex ./generate_admin_key.sh | tail -1)
  aws secretsmanager put-secret-value --region "$AWS_REGION" --secret-id "$SECRET_PREFIX/CONVEX_ADMIN_KEY" --secret-string "$key" >/dev/null
fi

# 5. n8n workflows (same steps as scripts/n8n-import.sh, against this stack).
until docker compose -f docker-compose.prod.yml logs n8n 2>&1 | grep -q "Editor is now accessible"; do sleep 3; done
n8n() { docker compose -f docker-compose.prod.yml exec -T n8n n8n "$@" 2>&1 | grep -v "license SDK" || true; }
n8n import:credentials --input=/lendloop/credentials/mailpit-smtp.json
n8n import:workflow --separate --input=/lendloop/workflows
for id in LendLoopErrorWf1 LendLoopNotifyWf LendLoopRemindWf; do n8n publish:workflow --id="$id"; done
# The CLI prints errors but exits 0, so check the result instead.
workflows=$(n8n list:workflow)
for id in LendLoopErrorWf1 LendLoopNotifyWf LendLoopRemindWf; do
  grep -q "^$id|" <<<"$workflows" || { echo "n8n workflow $id was not imported" >&2; exit 1; }
done
docker compose -f docker-compose.prod.yml restart n8n >/dev/null

# 6. Metrics every 5 minutes (systemd timer, survives reboots).
cat > /etc/systemd/system/lendloop-metrics.service <<UNIT
[Unit]
Description=Publish LendLoop operational metrics to CloudWatch
[Service]
Type=oneshot
Environment=AWS_REGION=$AWS_REGION SECRET_PREFIX=$SECRET_PREFIX
ExecStart=$APP_DIR/metrics.sh
UNIT
cat > /etc/systemd/system/lendloop-metrics.timer <<UNIT
[Unit]
Description=Every 5 minutes
[Timer]
OnBootSec=2min
OnUnitActiveSec=5min
[Install]
WantedBy=timers.target
UNIT
systemctl daemon-reload
systemctl enable --now lendloop-metrics.timer
echo "bootstrap complete"
